def a(n):
    if n <= 0:
        return 0
    if n == 1:
        return 0

    if n % 2 == 0:
        # n = 2k, k = n/2
        return 2 * a(n // 2) + n // 2
    else:
        # n = 2k+1, k = floor(n/2)
        k = n // 2
        # a_n = a_k + a_{k+1} + k
        return a(k) + a(k + 1) + k

target_n = 2025
result = a(target_n)
print(result)
